INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (1, '{Clavicle.r}', 'Clavícula', 'Hueso', 'Hueso largo en forma de S que conecta el esternón con la escápula, formando el único puente óseo entre el miembro superior y el esqueleto axial. Es uno de los huesos que más se fractura, típicamente por una caída sobre el hombro o el brazo extendido.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Gray''s Anatomy for Students"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (2, '{Scapula.r.}', 'Escápula', 'Hueso', 'Hueso plano triangular en la cara posterior del tórax, con la cavidad glenoidea que articula con la cabeza humeral. Su deslizamiento sobre la parrilla costal (ritmo escapulohumeral) es imprescindible para lograr el rango completo de elevación del brazo.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Rouvière - Anatomía Humana"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (3, '{Humerus.r}', 'Húmero', 'Hueso', 'Hueso largo del brazo; su cabeza se articula con la glenoides (hombro) y su extremo distal con el radio y el cúbito (codo). El cuello quirúrgico y la diáfisis media (por su relación con el nervio radial) son sitios frecuentes de fractura.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Gray''s Anatomy for Students"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (4, '{Radius.r}', 'Radio', 'Hueso', 'Hueso lateral del antebrazo (lado del pulgar). Rota alrededor del cúbito para producir la pronosupinación y transmite la mayor parte de la carga axial a través de la muñeca.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (5, '{Ulna.r}', 'Cúbito (Ulna)', 'Hueso', 'Hueso medial del antebrazo (lado del meñique). Su olécranon forma la punta del codo y su escotadura troclear estabiliza la articulación húmero-cubital durante la flexo-extensión.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (6, '{Scaphoid.r,"Lunate bone.r",Triquetrum.r,Pisiform.r,Trapezium.r,Trapezoid.r,Capitate.r,Hamate.r}', 'Huesos del carpo', 'Hueso', 'Ocho huesos cortos organizados en dos hileras: proximal (escafoides, semilunar, piramidal, pisiforme) y distal (trapecio, trapezoide, grande/capitate, ganchoso). El escafoides es el hueso del carpo que más se fractura y el de mayor riesgo de necrosis avascular por su vascularización retrógrada.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Kaplan Anatomy Lecture Notes"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (7, '{"1st metacarpal bone.r","2nd metacarpal bone.r","3rd metacarpal bone.r","4th metacarpal bone.r","5th metacarpal bone.r"}', 'Metacarpianos', 'Hueso', 'Cinco huesos largos que forman el esqueleto de la palma, entre el carpo y las falanges proximales. Sus cabezas distales forman los nudillos (articulaciones metacarpofalángicas).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (8, '{"Proximal phalanx of 1st finger.r","Proximal phalanx of 2d finger.r","Proximal phalanx of 3rd finger.r","Proximal phalanx of 4th finger.r","Proximal phalanx of 5th finger.r","Middle phalanx of 2d finger.r","Middle phalanx of 3rd finger.r","Middle phalanx of 4th finger.r","Middle phalanx of 5th finger.r","Distal phalanx of 1st finger.r","Distal phalanx of 2d finger.r","Distal phalanx of 3d finger.r","Distal phalanx of 4th finger.r","Distal phalanx of 5th finger.r"}', 'Falanges', 'Hueso', 'Huesos largos de los dedos: del 2º al 5º dedo hay falange proximal, media y distal; el pulgar solo tiene proximal y distal. Sus articulaciones interfalángicas permiten la flexo-extensión fina necesaria para la prensión.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (9, '{"Deltoid muscle.r","Acromial part of deltoid muscle.r","Clavicular part of deltoid muscle.r","Spinal part of deltoid muscle.r"}', 'Deltoides', 'Musculo', 'Músculo de 3 porciones que recubre el hombro: la clavicular flexiona, la acromial (media) abduce y la espinal (posterior) extiende. Es el principal motor de la abducción de hombro a partir de los 15°. Inervación: nervio axilar (C5-C6).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Cael - Anatomía Funcional"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (10, '{"Supraspinatus muscle.r"}', 'Supraespinoso', 'Musculo', 'Músculo del manguito rotador; inicia y asiste los primeros 15° de abducción del hombro y estabiliza la cabeza humeral contra la glenoides. Es el tendón que más se rompe del manguito rotador, cerca de su inserción en el troquíter. Inervación: nervio supraescapular (C5-C6).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Gray''s Anatomy for Students"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (11, '{"Infraspinatus muscle.r"}', 'Infraespinoso', 'Musculo', 'Músculo del manguito rotador; produce la rotación externa del hombro y estabiliza la cabeza humeral. Inervación: nervio supraescapular (C5-C6).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (12, '{"Teres minor muscle.r"}', 'Redondo menor', 'Musculo', 'Músculo del manguito rotador; rotador externo del hombro, sinergista del infraespinoso. Inervación: nervio axilar (C5-C6).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (13, '{"Subscapularis muscle.r"}', 'Subescapular', 'Musculo', 'Músculo del manguito rotador ubicado en la cara anterior de la escápula; es el principal rotador interno del hombro y estabiliza anteriormente la articulación glenohumeral. Inervación: nervios subescapulares (C5-C6).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (14, '{"Teres major muscle.r"}', 'Redondo mayor', 'Musculo', 'Extiende, aduce y rota internamente el hombro; suele describirse como "el asistente del dorsal ancho" por compartir acción e inserción cercana. Inervación: nervio subescapular inferior (C5-C7).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (15, '{"Latissimus dorsi.r"}', 'Dorsal ancho', 'Musculo', 'Músculo extenso de la espalda; extiende, aduce y rota internamente el hombro. Clave en movimientos de tracción (remo, dominadas). Inervación: nervio toracodorsal (C6-C8).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Cael - Anatomía Funcional"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (16, '{"Pectoralis major.r","Clavicular head of pectoralis major muscle.r","Sternocostal head of pectoralis major muscle.r","Abdominal head of pectoralis major muscle.r"}', 'Pectoral mayor', 'Musculo', 'Músculo de 3 cabezas (clavicular, esternocostal, abdominal) que aduce y rota internamente el hombro; la porción clavicular también flexiona. Inervación: nervios pectorales medial y lateral (C5-T1).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (17, '{"Pectoralis minor muscle.r"}', 'Pectoral menor', 'Musculo', 'Desciende y estabiliza la escápula, y asiste la elevación de las costillas en la inspiración forzada. Su acortamiento se asocia a síndrome de pinzamiento del desfiladero torácico. Inervación: nervio pectoral medial (C8-T1).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (18, '{"Serratus anterior muscle.r"}', 'Serrato anterior', 'Musculo', 'Protrae y rota ascendentemente la escápula, manteniéndola apoyada contra la parrilla costal. Su parálisis (lesión del nervio torácico largo) produce la clásica "escápula alada". Inervación: nervio torácico largo (C5-C7).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Gray''s Anatomy for Students"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (19, '{"Trapezius muscle.r","Ascending part of Trapezius muscle.r","Descending part of Trapezius muscle.r","Transverse part of trapezius muscle.r"}', 'Trapecio', 'Musculo', 'Músculo de 3 porciones: la descendente eleva la escápula, la transversa la retrae y la ascendente la deprime; en conjunto rotan ascendentemente la escápula durante la elevación del brazo. Inervación: nervio accesorio espinal (XI par craneal).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (20, '{"Rhomboid major muscle.r","Rhomboid minor muscle.r"}', 'Romboides', 'Musculo', 'Retraen y elevan levemente la escápula, fijándola contra la parrilla costal; antagonistas del serrato anterior en la rotación escapular. Inervación: nervio dorsal escapular (C4-C5).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (21, '{"Levator scapulae.r"}', 'Elevador de la escápula', 'Musculo', 'Eleva la escápula y, junto con el trapecio, ayuda a extender/lateralizar el cuello. Frecuentemente implicado en cervicalgias por tensión muscular. Inervación: nervio dorsal escapular y ramas cervicales (C3-C5).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (22, '{"Subclavius muscle.r"}', 'Subclavio', 'Musculo', 'Pequeño músculo entre la clavícula y la 1ª costilla; estabiliza y deprime levemente la articulación esternoclavicular, y protege el paquete neurovascular subyacente. Inervación: nervio subclavio (C5-C6).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (23, '{"Coracobrachialis muscle.r"}', 'Coracobraquial', 'Musculo', 'Flexiona y aduce débilmente el hombro; suele usarse como referencia quirúrgica porque el nervio musculocutáneo lo perfora. Inervación: nervio musculocutáneo (C5-C7).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (25, '{"Brachialis muscle.r"}', 'Braquial anterior', 'Musculo', 'Principal flexor del codo, independiente de la posición del antebrazo (a diferencia del bíceps). Inervación: nervio musculocutáneo (C5-C6).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (26, '{"Long head of triceps brachii.r","Lateral head of triceps brachii.r","Medial head of triceps brachii.r","Common tendon of triceps brachii.r"}', 'Tríceps braquial', 'Musculo', 'Músculo de 3 cabezas en la cara posterior del brazo; único extensor potente del codo. La cabeza larga también asiste la extensión y aducción del hombro. Inervación: nervio radial (C6-C8).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (27, '{"Anconeus muscle.r"}', 'Ancóneo', 'Musculo', 'Pequeño músculo posterolateral del codo; asiste la extensión y dinamiza/estabiliza la articulación durante el movimiento. Inervación: nervio radial (C7-C8, T1).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (28, '{"Brachioradialis muscle.r"}', 'Braquiorradial', 'Musculo', 'Flexor accesorio del codo, más activo cuando el antebrazo está en posición neutra (ni pronado ni supinado). Inervación: nervio radial (C5-C6).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (29, '{"Humeral head of pronator teres.r","Ulnar head of pronator teres.r"}', 'Pronador redondo', 'Musculo', 'Origen en el epicóndilo medial (epitróclea); pronador principal del antebrazo y flexor accesorio del codo. Su hipertrofia/tensión puede comprimir el nervio mediano (síndrome del pronador redondo). Inervación: nervio mediano (C6-C7).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (30, '{"Pronator quadratus.r"}', 'Pronador cuadrado', 'Musculo', 'Músculo profundo distal del antebrazo; pronador principal en movimientos rápidos o con el codo extendido. Inervación: nervio mediano/interóseo anterior (C8-T1).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (31, '{Supinator.r}', 'Supinador', 'Musculo', 'Rodea la porción proximal del radio; supina el antebrazo junto con el bíceps braquial. El nervio radial (rama interósea posterior) lo atraviesa y puede comprimirse ahí (síndrome del túnel radial). Inervación: nervio radial (C5-C6).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (32, '{"Flexor carpi radialis.r"}', 'Flexor radial del carpo', 'Musculo', 'Flexiona y desvía radialmente la muñeca. Origen en el epicóndilo medial. Inervación: nervio mediano (C6-C7).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (33, '{"Humeral head of flexor carpi ulnaris.r","Ulnar head of flexor carpi ulnaris.r","Common tendon of flexor carpi ulnaris.r"}', 'Flexor cubital del carpo', 'Musculo', 'Flexiona y desvía cubitalmente la muñeca. El nervio cubital pasa entre sus dos cabezas, sitio de posible compresión distal al codo. Inervación: nervio cubital (C7-T1).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (35, '{"Flexor digitorum superficialis humero-ulnar head.r","Flexor digitorum superficialis radial head.r"}', 'Flexor superficial de los dedos', 'Musculo', 'Flexiona las articulaciones interfalángicas proximales del 2º al 5º dedo (y asiste la flexión de muñeca y metacarpofalángicas). Inervación: nervio mediano (C7-T1).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (36, '{"Flexor digitorum profundus.r"}', 'Flexor profundo de los dedos', 'Musculo', 'Único flexor de las articulaciones interfalángicas distales del 2º al 5º dedo. Inervación mixta: nervio mediano (2º-3º dedo) y nervio cubital (4º-5º dedo).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (34, '{"Palmaris longus muscle.r","Aponeurosis palmaris.r"}', 'Palmar largo', 'Musculo', 'Tensa la aponeurosis palmar; ausente congénitamente hasta en ~15% de la población sin repercusión funcional. Inervación: nervio mediano (C7-C8).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (37, '{"Flexor pollicis longus.r"}', 'Flexor largo del pulgar', 'Musculo', 'Único flexor de la articulación interfalángica del pulgar. Inervación: nervio mediano/interóseo anterior (C8-T1).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (38, '{"Extensor carpi radialis longus.r"}', 'Extensor radial largo del carpo', 'Musculo', 'Extiende y desvía radialmente la muñeca. Origen en la cresta supracondílea lateral del húmero. Inervación: nervio radial (C6-C7).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (39, '{"Extensor carpi radialis brevis.r"}', 'Extensor radial corto del carpo', 'Musculo', 'Extiende la muñeca; su origen en el epicóndilo lateral es el sitio más frecuentemente afectado en la epicondilitis lateral ("codo de tenista"). Inervación: nervio radial (C7-C8).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Gray''s Anatomy for Students"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (40, '{"Humeral head of extensor carpi ulnaris.r","Ulnar head of extensor carpi ulnaris.r","Common tendon of extensor carpi ulnaris.r"}', 'Extensor cubital del carpo', 'Musculo', 'Extiende y desvía cubitalmente la muñeca. Inervación: nervio radial/interóseo posterior (C7-C8).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (42, '{"Extensor digiti minimi.r"}', 'Extensor propio del meñique', 'Musculo', 'Extensor accesorio del 5º dedo, independiente del extensor común. Inervación: nervio radial/interóseo posterior (C7-C8).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (43, '{"Extensor indicis.r"}', 'Extensor propio del índice', 'Musculo', 'Extensor accesorio del 2º dedo (índice), permite extenderlo de forma independiente de los demás. Inervación: nervio radial/interóseo posterior (C7-C8).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (44, '{"Abductor pollicis longus.r"}', 'Abductor largo del pulgar', 'Musculo', 'Abduce y extiende el 1º metacarpiano; forma, junto al extensor corto del pulgar, el primer compartimento extensor (afectado en la tenosinovitis de De Quervain). Inervación: nervio radial/interóseo posterior (C7-C8).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (45, '{"Extensor pollicis brevis.r"}', 'Extensor corto del pulgar', 'Musculo', 'Extiende la articulación metacarpofalángica del pulgar. Comparte el primer compartimento extensor con el abductor largo del pulgar. Inervación: nervio radial/interóseo posterior (C7-C8).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (46, '{"Extensor pollicis longus.r"}', 'Extensor largo del pulgar', 'Musculo', 'Extiende la articulación interfalángica del pulgar. Ocupa el tercer compartimento extensor, angulándose alrededor del tubérculo de Lister. Inervación: nervio radial/interóseo posterior (C7-C8).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (47, '{"Abductor pollicis brevis.r","Deep head of flexor pollicis brevis.r","Superficial head of flexor pollicis brevis.r","Opponens pollicis muscle.r"}', 'Músculos tenares', 'Musculo', 'Grupo de músculos en la base del pulgar (abductor corto, flexor corto y oponente) responsables de los movimientos finos del pulgar, en especial la oposición. Su atrofia es un signo característico y tardío del síndrome del túnel carpiano. Inervación: nervio mediano.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Kaplan Anatomy Lecture Notes"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (49, '{"Abductor digiti minimi.r","Flexor digiti minimi brevis of hand.r","Opponens digiti minimi muscle of hand.r","Palmaris brevis muscle.r"}', 'Músculos hipotenares', 'Musculo', 'Grupo de músculos en la base del 5º dedo (abductor, flexor corto, oponente y palmar cutáneo) que permiten sus movimientos finos y ahuecan la palma. Inervación: nervio cubital.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (50, '{"1st dorsal interosseus of hand.r","2nd dorsal interosseus of hand.r","3rd dorsal interosseus of hand.r","4th dorsal interosseus of hand.r"}', 'Interóseos dorsales', 'Musculo', 'Abducen los dedos respecto al eje del 3º dedo (separan los dedos) y asisten la flexión metacarpofalángica con extensión interfalángica. Inervación: nervio cubital (rama profunda).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (51, '{"1st palmar interosseus of hand.r","2nd palmar interosseus of hand.r","3rd palmar interosseus of hand.r"}', 'Interóseos palmares', 'Musculo', 'Aducen los dedos hacia el eje del 3º dedo (juntan los dedos) y asisten la flexión metacarpofalángica con extensión interfalángica. Inervación: nervio cubital (rama profunda).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (52, '{"1st lumbrical of hand.r","2nd lumbrical of hand.r","3rd lumbrical of hand.r","4th lumbrical of hand.r"}', 'Lumbricales', 'Musculo', 'Flexionan las articulaciones metacarpofalángicas mientras extienden las interfalángicas, coordinando el movimiento de "garra funcional" de la mano. Inervación mixta: nervio mediano (1º-2º) y nervio cubital (3º-4º).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (48, '{"Oblique head of adductor pollicis.r","Transverse head of adductor pollicis.r","Adductor pollicis.r"}', 'Aductor del pulgar', 'Musculo', 'Aduce el pulgar hacia la palma; principal músculo de la fuerza de pinza entre el pulgar y el índice. Inervación: nervio cubital (rama profunda).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (24, '{"Long head of biceps brachii.r","Short head of biceps brachii.r","Common tendon of biceps brachii.r","Bicipital aponeurosis.r","Long head of biceps brachii tendon sheath.r"}', 'Bíceps braquial', 'Musculo', 'Músculo de 2 cabezas; flexiona el codo y es el supinador más potente del antebrazo, especialmente con el codo flexionado. La tendinopatía de la porción larga (en la corredera bicipital) suele asociarse a patología del manguito rotador. Inervación: nervio musculocutáneo (C5-C6).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Cael - Anatomía Funcional"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (41, '{"Extensor digitorum.r","Extensor hood of 2nd finger.r","Extensor hood of 3rd finger.r","Extensor hood of 4th finger.r","Extensor hood of 5th finger.r"}', 'Extensor de los dedos', 'Musculo', 'Extiende las articulaciones metacarpofalángicas y, mediante el aparato extensor, asiste la extensión interfalángica del 2º al 5º dedo. Inervación: nervio radial/interóseo posterior (C7-C8).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 00:17:11.979256+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (53, '{"Superficial transverse metacarpal lig."}', 'Ligamento metacarpiano transverso superficial', 'Ligamento', 'Banda fibrosa superficial en la base de los dedos que conecta las vainas de los tendones flexores entre sí, contribuyendo a la estabilidad del arco transverso distal de la mano.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 16:50:56.440091+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (60, '{"Sesamoid bones of hand.r"}', 'Sesamoideos de la mano', 'Hueso', 'Pequeños huesos redondeados incluidos dentro de tendones, típicamente presentes en la articulación metacarpofalángica del pulgar. Reducen la fricción y mejoran la eficiencia mecánica del tendón que los contiene.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 16:50:56.491659+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (61, '{"C5 root.r","C6 root.r","C7 root.r","C8 root.r","T1 root.r","Superior trunk of brachial plexus.r","Middle trunk of brachial plexus.r","Inferior trunk of brachial plexus.r","Anterior divisions of brachial plexus.r","Posterior divisions of brachial plexus.r","Lateral cord of brachial plexus.r","Medial cord of brachial plexus.r","Posterior cord of brachial plexus.r"}', 'Plexo Braquial (raíces, troncos, divisiones y fascículos)', 'Nervio', 'Red nerviosa formada por las ramas ventrales de C5 a T1, organizada secuencialmente en raíces, troncos (superior, medio, inferior), divisiones (anterior y posterior) y fascículos (lateral, medial y posterior, nombrados según su relación con la arteria axilar). De los fascículos nacen los nervios terminales que inervan todo el miembro superior.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Neuroanatomía Clínica, Snell (7ª ed.)"}', '2026-08-16 16:59:05.636699+00', '{"Parálisis de Erb-Duchenne (C5-C6): lesión alta, produce el clásico \"brazo del mesero\" (hombro en rotación interna, codo en extensión)","Parálisis de Klumpke (C8-T1): lesión baja, afecta principalmente la musculatura intrínseca de la mano","Lesiones por tracción (ej. accidentes con abducción forzada del brazo): pueden producir avulsiones radiculares con mal pronóstico","La exploración de miotomas y dermatomas es clave para localizar el nivel de la lesión dentro del plexo"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (62, '{"Median nerve.r","Lateral root of median nerve.r","Medial root of median nerve.r","Median nerve Palmar br","Median nerve Recurrent br","Median nerve Common palmar digital nerve of the thumb","Median nerve Common palmar digital nerves","Median nerve Proper palmar digital nerves","Median nerve Proper palmar digital nerves of the thumb"}', 'Nervio Mediano', 'Nervio', 'Se forma por la unión de raíces de los fascículos lateral y medial del plexo braquial (C6-T1). Desciende por el brazo sin dar ramas, cruza el codo medial a la arteria braquial, atraviesa el pronador redondo e inerva la mayoría de los flexores del antebrazo y los músculos tenares, además de la sensibilidad palmar de los primeros 3½ dedos.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Neuroanatomía Clínica, Snell (7ª ed.)","Kaplan Anatomy Lecture Notes"}', '2026-08-16 16:59:05.636699+00', '{"Síndrome del túnel carpiano: compresión bajo el retináculo flexor; la neuropatía compresiva más frecuente del miembro superior","Síndrome del pronador redondo: compresión más proximal, a nivel del codo/antebrazo","La rama recurrente motora (tenar) es superficial y vulnerable en incisiones palmares proximales","Signo de la mano en bendición: al intentar hacer un puño, el 1º y 2º dedo no flexionan por lesión alta del mediano"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (56, '{"Lumbar vertebra (L1)","Lumbar vertebra (L2)","Lumbar vertebra (L3)","Lumbar vertebra (L4)","Lumbar vertebra (L5)","Vertebra L4 art cart","Vertebra L3 art cart.","Annulus fibrosus L4 L5","Vertebra L5 art cart","Annulus fibrosus L2 L3","Annulus fibrosus L3 L4","Vertebra L2 art cart","Annulus fibrosus L5 S1","Vertebra L1 art cart","Nucleus pulposus L1-S1","Annulus fibrosus L1 L20"}', 'Columna Lumbar', 'Hueso', 'Cinco vértebras de cuerpo robusto, las de mayor tamaño de la columna móvil, adaptadas para soportar la mayor parte del peso corporal en bipedestación. Es origen distal del dorsal ancho a través de la fascia toracolumbar.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Rouvière - Anatomía Humana"}', '2026-08-16 16:50:56.491659+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (57, '{Sacrum,"art cart of sacrum lumbosacral joint","art cart of sacrum art process.r"}', 'Sacro', 'Hueso', 'Hueso triangular formado por la fusión de 5 vértebras sacras, que conecta la columna con la pelvis a través de las articulaciones sacroilíacas. Aporta origen a la fascia toracolumbar, relacionada con el dorsal ancho.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 16:50:56.491659+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (59, '{"Manubrium of sternum","Body of sternum","Xiphoid process"}', 'Esternón', 'Hueso', 'Hueso plano medio-anterior del tórax formado por manubrio y cuerpo, que se articula con las clavículas y los primeros 7 pares de costillas. Es sitio de origen de la cabeza esternocostal del pectoral mayor. El ángulo esternal (entre manubrio y cuerpo) es un reparo palpatorio clave que marca el nivel de la 2ª costilla.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 16:50:56.491659+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (63, '{"Ulnar nerve.r","Ulnar nerve Communicating br","Ulnar nerve Deep br","Ulnar nerve Dorsal cutaneous br","Ulnar nerve Palmar cutaneous br","Ulnar nerve Superficial br Common palmar digital n","Ulnar nerve Superficial br Proper palmar digital nn"}', 'Nervio Cubital (Ulnar)', 'Nervio', 'Rama terminal del fascículo medial del plexo braquial (C8-T1). Desciende por el brazo, pasa posterior al epicóndilo medial del húmero (canal cubital) y sigue por el antebrazo hasta la mano, donde inerva el flexor cubital del carpo, la mitad cubital del flexor profundo de los dedos y la mayoría de los músculos intrínsecos de la mano.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Neuroanatomía Clínica, Snell (7ª ed.)"}', '2026-08-16 16:59:05.636699+00', '{"Neuropatía cubital en el codo (síndrome del túnel cubital): el nervio es muy superficial en el canal cubital, la segunda neuropatía compresiva más frecuente del miembro superior","Síndrome del canal de Guyon: compresión distal, a nivel de la muñeca","Mano en garra cubital: hiperextensión de metacarpofalángicas con flexión de interfalángicas del 4º y 5º dedo por parálisis de lumbricales/interóseos","Signo de Froment: compensación con el flexor largo del pulgar (mediano) al perderse la fuerza del aductor del pulgar (cubital)"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (64, '{"Radial nerve.r","Radial nerve (deep branch).r","Radial nerve (dorsal digital nn).r","Radial nerve (inferior lateral brachial cutaneous n).r","Radial nerve (posterior antebrachial cutaneous n).r","Radial nerve (posterior brachial cutaneous n).r","Radial nerve (posterior interosseus n).r","Radial nerve (superficial br).r"}', 'Nervio Radial', 'Nervio', 'Rama terminal del fascículo posterior del plexo braquial (C5-T1). Desciende por el surco radial del húmero, inervando el tríceps braquial, y continúa hacia el antebrazo donde se divide en una rama profunda (motora, se convierte en el nervio interóseo posterior) y una rama superficial (sensitiva, dorso de la mano).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Neuroanatomía Clínica, Snell (7ª ed.)"}', '2026-08-16 16:59:05.636699+00', '{"Mano péndula (wrist drop): parálisis de los extensores de muñeca y dedos, típica de la lesión del radial en la diáfisis humeral (ej. fractura de húmero)","Síndrome del túnel radial / del interóseo posterior: compresión a nivel del supinador (arcada de Fröhse)","Es el nervio más frecuentemente lesionado en fracturas de la diáfisis humeral, por su relación directa con el hueso en el surco radial"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (65, '{"Musculocutaneus nerve.r","Musculocutaneus nerve  - lateral antebrachial cutaneous nerve.r"}', 'Nervio Musculocutáneo', 'Nervio', 'Rama terminal del fascículo lateral del plexo braquial (C5-C7). Perfora el coracobraquial e inerva los tres flexores del brazo (coracobraquial, bíceps braquial, braquial anterior); su rama terminal continúa como nervio cutáneo antebraquial lateral, sensitivo para la cara lateral del antebrazo.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 16:59:05.636699+00', '{"Poco frecuente de lesionar de forma aislada; su compromiso reduce marcadamente la fuerza de flexión de codo y supinación","Su porción cutánea terminal puede lesionarse en cirugías de la fosa cubital o toma de venas para vías"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (66, '{"Axillary nerve - superior lateral br cutaneous nerve.r"}', 'Nervio Axilar', 'Nervio', 'Rama terminal del fascículo posterior del plexo braquial (C5-C6). Pasa por el espacio cuadrilátero junto a la arteria circunfleja humeral posterior e inerva el deltoides y el redondo menor; su rama cutánea (representada en este modelo) da sensibilidad a la piel sobre el deltoides.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Neuroanatomía Clínica, Snell (7ª ed.)"}', '2026-08-16 16:59:05.636699+00', '{"Es el nervio más frecuentemente lesionado en luxaciones anteriores de hombro y fracturas del cuello quirúrgico del húmero","Su lesión produce debilidad de la abducción de hombro y una zona de anestesia característica sobre el deltoides (\"parche del regimiento\")"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (67, '{"Suprascapular nerve.r"}', 'Nervio Supraescapular', 'Nervio', 'Nace del tronco superior del plexo braquial (C5-C6). Pasa por la escotadura escapular bajo el ligamento transverso superior de la escápula e inerva el supraespinoso y el infraespinoso.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 16:59:05.636699+00', '{"Síndrome del atrapamiento supraescapular: compresión en la escotadura escapular, causa de dolor posterior de hombro y debilidad de la rotación externa/abducción inicial, a veces confundido con patología del manguito rotador"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (68, '{"Long thoracic nerve.r"}', 'Nervio Torácico Largo', 'Nervio', 'Nace directamente de las raíces C5-C7, antes de la formación de los troncos. Desciende por la cara lateral del tórax e inerva exclusivamente el serrato anterior.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 16:59:05.636699+00', '{"Su lesión (ej. en cirugía de mama/axila) produce la clásica \"escápula alada\", por parálisis del serrato anterior"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (69, '{"Dorsal scapular nerve.r"}', 'Nervio Dorsal Escapular', 'Nervio', 'Nace de la raíz C5. Atraviesa el músculo escaleno medio e inerva el elevador de la escápula y los romboides mayor y menor.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 16:59:05.636699+00', '{"Su lesión debilita la retracción y estabilización medial de la escápula, contribuyendo a alteraciones del ritmo escapulohumeral"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (70, '{"Upper subscapular nerve.r","Lower subscapular nerve.r"}', 'Nervios Subescapulares (superior e inferior)', 'Nervio', 'Ramas del fascículo posterior del plexo braquial. El subescapular superior inerva la porción superior del subescapular; el inferior inerva la porción inferior del subescapular y el redondo mayor.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 16:59:05.636699+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (71, '{"Lateral pectoral nerve.r","Medial pectoral nerve.r"}', 'Nervios Pectorales (medial y lateral)', 'Nervio', 'El pectoral lateral (del fascículo lateral) inerva principalmente la cabeza clavicular del pectoral mayor; el pectoral medial (del fascículo medial) inerva el pectoral menor y contribuye a la cabeza esternocostal del pectoral mayor.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 16:59:05.636699+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (72, '{"Subclavian nerve.r"}', 'Nervio Subclavio', 'Nervio', 'Nace del tronco superior del plexo braquial (C5-C6). Desciende por delante de la arteria subclavia e inerva el músculo subclavio.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 16:59:05.636699+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (73, '{"Medial brachial cutaneous nerve.r","Medial antebrachial cutaneous nerve.r"}', 'Nervios Cutáneos Mediales del Brazo y Antebrazo', 'Nervio', 'Ramas puramente sensitivas del fascículo medial del plexo braquial. Dan sensibilidad a la piel de la cara medial del brazo y del antebrazo respectivamente, sin componente motor.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 16:59:05.636699+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (74, '{"Subclavian artery.r","Brachiocephalic artery.r","Common carotid artery.r","Vertebral artery.r","Costocervical trunk.r","Thyrocervical trunk.r","Transverse cervical artery.r","Superficial branch of Transverse cervical artery.r","Internal thoracic artery.r","Dorsal scapular artery (Deep br of transverse cervical a.).r"}', 'Arteria Subclavia (origen y ramas cervicotorácicas)', 'Vaso', 'Continúa a la arteria braquiocefálica (derecha) o nace directamente del cayado aórtico (izquierda); se convierte en arteria axilar al cruzar el borde lateral de la 1ª costilla. En su trayecto da ramas hacia el cuello y la pared torácica superior (vertebral, torácica interna, troncos tirocervical y costocervical, cervical transversa) que no irrigan directamente el miembro superior pero forman parte de su origen vascular.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Rouvière - Anatomía Humana"}', '2026-08-16 17:01:32.649835+00', '{"Es la referencia arterial para el bloqueo del plexo braquial por vía supraclavicular","El síndrome del desfiladero torácico puede comprimir la arteria subclavia junto con el plexo braquial entre los escalenos o bajo la clavícula","La arteria vertebral (rama de la subclavia) irriga el tronco encefálico; su disección o compresión puede producir síntomas neurológicos centrales"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (75, '{"Axillary artery.r","Superior thoracic artery.r","Thoracoacromial artery Acromial br.r","Thoracoacromial artery Deltoid br.r","Thoracoacromial artery Pectoral br.r","Lateral thoracic artery.r","Subscapular artery.r","Thoracodorsal artery.r","Circumflex scapular artery.r","Anterior circumflex humeral artery.r","Posterior circumflex humeral artery.r","Suprascapular artery.r"}', 'Arteria Axilar y sus ramas', 'Vaso', 'Continuación de la subclavia desde el borde lateral de la 1ª costilla hasta el borde inferior del redondo mayor, donde pasa a llamarse arteria braquial. Irriga la cintura escapular y la pared torácica lateral a través de sus ramas: torácica superior, toracoacromial (con sus ramas acromial, deltoidea y pectoral), torácica lateral, subescapular (que da la toracodorsal y la circunfleja escapular) y las circunflejas humerales anterior y posterior.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:01:32.649835+00', '{"Relación estrecha con los fascículos del plexo braquial: ambos se lesionan juntos en traumatismos axilares o luxaciones de hombro","La circunfleja humeral posterior acompaña al nervio axilar por el espacio cuadrilátero; su compromiso vascular puede coexistir con lesión nerviosa","Sitio de acceso para cateterismo en algunos procedimientos vasculares"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (76, '{"Brachial artery.r","Deep artery of arm.r","Superior ulnar collateral artery.r","Inferior ulnar collateral artery.r","Medial collateral artery.r","Radial collateral artery.r","Middle collateral artery.r"}', 'Arteria Braquial y sus ramas', 'Vaso', 'Continuación de la axilar; desciende por la cara medial del brazo junto al nervio mediano y se divide en radial y cubital en la fosa cubital. Da la arteria profunda del brazo (que acompaña al nervio radial) y las colaterales cubitales superior e inferior, que participan en la red anastomótica alrededor del codo.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:01:32.649835+00', '{"Sitio estándar de auscultación de la presión arterial (con el manguito) y de palpación del pulso braquial","Puede lesionarse en fracturas supracondíleas de húmero en niños, con riesgo de síndrome compartimental (contractura de Volkmann) si se compromete el flujo distal","La red anastomótica periarticular del codo permite circulación colateral si se ocluye un segmento localizado"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (77, '{"Radial artery.r","Radial recrurrent artery.r","Dorsalis pollicis.r","Dorsalis indicis.r","Radialis indicis.r","Princeps pollicis arteries.r"}', 'Arteria Radial y sus ramas', 'Vaso', 'Rama lateral de bifurcación de la braquial; desciende superficial en el antebrazo (lateral al flexor radial del carpo) y cruza la tabaquera anatómica antes de hundirse en la palma para formar el arco palmar profundo. Da ramas hacia el pulgar y el índice.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:01:32.649835+00', '{"Sitio clásico de palpación del pulso radial y de punción arterial (gasometría, catéteres)","Zona de acceso para cateterismo cardíaco transradial","El test de Allen evalúa la permeabilidad de la arcada palmar (radial + cubital) antes de una punción radial"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (78, '{"Ulnar artery.r","Ulnar artery (dorsal carpal br).r","Anterior ulnar recurrent artery.r","Posterior ulnar recurrent artery.r","Common interosseous artery.r","Anterior interosseous artery.r","Posterior interosseous artery.r","Interosseous recurrent artery.r"}', 'Arteria Cubital y sus ramas', 'Vaso', 'Rama medial de bifurcación de la braquial, de mayor calibre que la radial; desciende por el antebrazo junto al nervio cubital y forma el arco palmar superficial. Da la arteria interósea común, que se divide en interósea anterior y posterior para irrigar el compartimento profundo del antebrazo.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:01:32.649835+00', '{"Forma, junto con la radial, la doble irrigación de la mano que permite el test de Allen","Su rama interósea anterior acompaña al nervio homónimo y puede lesionarse en fracturas complejas del antebrazo"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (79, '{"Superficial palmar arch.r","Deep palmar arch.r","Dorsal carpal arch.r","Dorsal carpal network.r","Palmar carpal branches.r","Common palmar digital arteries.r","Proper palmar digital arteries.r","Palmar metacarpal arteries.r","Dorsal metacarpal arteries.r","Dorsal digital arteries.r","Perforating arteries.r"}', 'Arcos y Redes Arteriales de la Mano', 'Vaso', 'La mano recibe doble irrigación a través de dos arcos palmares (superficial, principalmente de la cubital, y profundo, principalmente de la radial) que se anastomosan entre sí, además de redes carpianas dorsales. De estos arcos nacen las arterias digitales palmares y metacarpianas que irrigan los dedos.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:01:32.649835+00', '{"La rica anastomosis entre arcos y redes explica por qué la mano tolera relativamente bien la oclusión aislada de una sola arteria de origen","Relevante en reimplantes digitales y colgajos quirúrgicos de mano"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (98, '{"Intertendinous connections of extensor digitorum","Lateral band of 2nd finger","Lateral band of 3rd finger","Lateral band of 4th finger","Lateral band of 5th finger"}', 'Aparato Extensor de los Dedos', 'Ligamento', 'Expansión tendinosa compleja en el dorso de cada dedo formada por el tendón del extensor de los dedos, las bandas laterales (que reciben fibras de los lumbricales e interóseos) y conexiones intertendinosas, que coordina la extensión simultánea de las articulaciones metacarpofalángica e interfalángicas.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:04:53.461089+00', '{"Dedo en martillo (mallet finger): avulsión o rotura del aparato extensor en su inserción distal, con caída de la falange distal","Deformidad en ojal (boutonnière): rotura de la banda central que permite que las bandas laterales se desplacen palmarmente, invirtiendo su función"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (80, '{"Arm superficial vein-Basilic vein.r","Arm superficial vein-Cephalic vein.r","Arm superficial vein-Median antebrachial vein.r","Arm superficial vein-Median cubital vein.r","Superficial veins of upper limb.r","Lateral thoracic vein.r","Dorsal venous network","Dorsal digital veins","Dorsal metatarsal veins","Palmar venous network","Palmal digital veins","Superficial palmar venous arch"}', 'Venas Superficiales del Miembro Superior', 'Vaso', 'Red venosa subcutánea, visible y palpable, formada principalmente por las venas cefálica (borde lateral) y basílica (borde medial), unidas en el codo por la vena mediana cubital, además de redes venosas dorsales y palmares de la mano.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:01:32.649835+00', '{"La vena mediana cubital es el sitio más frecuente de venopunción y extracción de sangre por su calibre, fijación y accesibilidad","La vena cefálica es una vía de acceso frecuente para catéteres venosos centrales de inserción periférica (PICC) y para fístulas arteriovenosas en diálisis","La flebitis superficial es una complicación frecuente de accesos venosos periféricos prolongados"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (81, '{"Deep veins of the arm.r","Axillary vein.r","Subclavian vein.r","External jugular vein.r","Radial veins.r","Ulnar veins.r","Anterior interosseous veins.r","Posterior interosseous veins.r","Deep venous palmar arch","Palmar metacarpal veins","Intercapitular veins"}', 'Venas Profundas del Miembro Superior', 'Vaso', 'Acompañan a las arterias homónimas (generalmente dobles, venae comitantes) y drenan en la vena axilar, que continúa como vena subclavia y luego se une a la yugular interna para formar el tronco venoso braquiocefálico.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:01:32.649835+00', '{"Trombosis venosa profunda del miembro superior: menos frecuente que en el miembro inferior, pero relevante en contexto de catéteres venosos centrales o esfuerzo repetitivo (síndrome de Paget-Schroetter)","La vena subclavia es un sitio habitual de acceso venoso central"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (54, '{"Atlas (C1)","Axis (C2)","Cervical vertebra (C3)","Cervical vertebra (C4)","Cervical vertebra (C5)","Cervical vertebra (C6)","Cervical vertebra (C7)","annulus fibrosus C3 C4","Vertebra C3 art cart","annulus fibrosus C5 C6","Nucleus pulposus C2-T1","Vertebra C5 art cart","annulus fibrosus C2 C3","annulus fibrosus C6 C7","annulus fibrosus C7 T1","Vertebra C7 art cart","annulus fibrosus C4 C5","Vertebra C6 art cart","Vertebra C4 art cart","art cart of Atlas  C1","art cart of Axis  C2"}', 'Columna Cervical', 'Hueso', 'Siete vértebras que forman el segmento más móvil de la columna. El atlas (C1) no tiene cuerpo vertebral y sostiene el cráneo; el axis (C2) aporta la apófisis odontoides sobre la que rota el atlas. De C3 a C7 son vértebras típicas que permiten un amplio rango de flexo-extensión y rotación cervical, y sirven de origen a músculos como el trapecio, el elevador de la escápula y los romboides.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Rouvière - Anatomía Humana"}', '2026-08-16 16:50:56.491659+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (55, '{"Thoracic vertebra (T1)","Thoracic vertebra (T2)","Thoracic vertebra (T3)","Thoracic vertebra (T4)","Thoracic vertebra (T5)","Thoracic vertebra (T6)","Thoracic vertebra (T7)","Thoracic vertebra (T8)","Thoracic vertebra (T9)","Thoracic vertebra (T10)","Thoracic vertebra (T11)","Thoracic vertebra (T12)","Annulus fibrosus T2 T3","Annulus fibrosus T12 L1","Annulus fibrosus T5 T6","Vertebra T2 art cart","Vertebra T10 art cart","Vertebra T12 art cart","Annulus fibrosus T6 T7","Nucleus pulposus T1-L1","Vertebra T7 art cart","Annulus fibrosus T7 T8","Annulus fibrosus T8 T9","Vertebra T6 art cart","Annulus fibrosus T10 T11","Annulus fibrosus T9 T10","Vertebra T9 art cart","Annulus fibrosus T1 T2","Annulus fibrosus T4 T5","Vertebra T3 art cart","Annulus fibrosus T3 T4","Vertebra T5 art cart","Vertebra T4 art cart","Vertebra T8 art cart","Annulus fibrosus T11 T12","Vertebra T11 art cart","Vertebra T1 art cart"}', 'Columna Torácica', 'Hueso', 'Doce vértebras que se articulan con las costillas correspondientes, formando la caja torácica junto con el esternón. Su movilidad es menor que la cervical o lumbar por esta relación costovertebral, priorizando la estabilidad y protección de los órganos torácicos. T7 se ubica aproximadamente a la altura del ángulo inferior de la escápula en bipedestación, un reparo clínico frecuente.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Rouvière - Anatomía Humana"}', '2026-08-16 16:50:56.491659+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (58, '{"Rib (1st).r","Rib (2nd).r","Rib (3rd).r","Rib (4th).r","Rib (5th).r","Rib (6th).r","Rib (7th).r","Rib (8th).r","Rib (9th).r","Rib (10th).r","Rib (11th).r","Rib (12th).r","Costal cart of 12th.rib.r","Costal cart of 4th.rib.r","Costal cart of 3rd.rib.r","7th rib art cart of head.r","8th rib art cart of head.r","4th rib art cart of head.r","7th rib art cart of tubercle.r","art cart of sternocostal joint on manubrium.r","5th rib art cart of tubercle.r","Costal cart of 5th.rib.r","10th rib art cart of head.r","2nd rib art cart of head.r","12th rib art cart of head.r","9th rib art cart of tubercle.r","2nd rib art cart of tubercle.r","3rd rib art cart of head.r","Costal cart of 1st.rib.r","6th rib art cart of head.r","Costal cart of 8th.rib.r","Costal cart of 10th.rib.r","Costal cart of 6th.rib.r","Costal cart of 9th.rib.r","1st rib art cart of head.r","6th rib art cart of tubercle.r","art cart of sternocostal joints on sternal body.r","9th rib art cart of head.r","3rd rib art cart of tubercle.r","4th rib art cart of tubercle.r","10th rib art cart of tubercle.r","1st rib art cart of tubercle.r","Costal cart of 2nd.rib.r","5th rib art cart of head.r","Costal cart of 11th.rib.r","Costal cart of 7th.rib.r","11th rib art cart of head.r","8th rib art cart of tubercle.r"}', 'Costillas', 'Hueso', 'Doce pares de huesos planos y curvos que forman la caja torácica junto con las vértebras torácicas y el esternón (a través de los cartílagos costales). Sirven de origen al serrato anterior y al pectoral menor, entre otros músculos del miembro superior. Las costillas 11ª y 12ª son "flotantes" (no se articulan con el esternón).', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Rouvière - Anatomía Humana"}', '2026-08-16 16:50:56.491659+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (82, '{"Sternoclavicular capsule.r","Anterior sternoclavicular ligament.r","Posterior Sternoclavicular ligament.r","Interclavicular ligament.r","Costoclavicular ligament.r","Articular cartilage of sternoclavicular joint on clavicle.r","Articular disc of steroclavicular joint.r","art cart of sternoclavicular joint on manubrium.r"}', 'Articulación Esternoclavicular', 'Ligamento', 'Única articulación verdadera entre el miembro superior y el esqueleto axial. Es una articulación en silla de montar con un disco articular interpuesto, estabilizada por los ligamentos esternoclavicular anterior/posterior, interclavicular y costoclavicular.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:04:53.461089+00', '{"Es la articulación más frecuentemente estable de la cintura escapular; su luxación es infrecuente y requiere trauma de alta energía","La luxación posterior es poco común pero potencialmente grave por su proximidad a grandes vasos y tráquea"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (83, '{"Acromioclavicular capsule.r","Acromioclavicular disc.r","Acromioclavicular ligament.r","Coracoclavicular ligament.r","Conoid ligament (part of coracoclavicular ligament).r","Trapezoid ligament (part of coracoclavicular ligament).r","Coraco-acromial ligament.r","Superior transverse scapular ligament.r","Inferior transverse scapular ligament.r","Articular cartilage of acromioclavicular joint on clavicle.r","Articular cartilage of acromioclavicular joint on scapula.r"}', 'Articulación Acromioclavicular', 'Ligamento', 'Articulación plana entre el acromion y la clavícula, estabilizada principalmente por el ligamento acromioclavicular (estabilidad horizontal) y el coracoclavicular (estabilidad vertical, con sus fascículos conoide y trapezoide). El ligamento coracoacromial forma parte del arco que protege al manguito rotador.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:04:53.461089+00', '{"Lesión acromioclavicular (\"luxación de hombro AC\"): frecuente en caídas sobre el hombro con el brazo aducido (ej. ciclismo, rugby), clasificada según el grado de ruptura ligamentaria (Rockwood)","El ligamento coracoacromial puede contribuir al pinzamiento subacromial si se engrosa"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (84, '{"Articular capsule of glenohumeral joint.r","Glenoid labrum.r","Coracohumeral ligament.r","Superior glenohumeral ligament.r","Middle glenohumeral ligament.r","Inferior glenohumeral ligament.r","Transverse humeral ligament.r","Art cart of humerus head​.r","Articular cartilage of glenohumeral joint on scapula.r"}', 'Articulación Glenohumeral (Hombro)', 'Ligamento', 'Articulación esferoidea de gran movilidad y escasa congruencia ósea, estabilizada principalmente por partes blandas: la cápsula articular, el rodete glenoideo (que profundiza la cavidad glenoidea) y los ligamentos glenohumerales (superior, medio e inferior), reforzados por el manguito rotador.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Gray''s Anatomy for Students"}', '2026-08-16 17:04:53.461089+00', '{"Es la articulación que más se luxa del cuerpo, predominantemente hacia anterior","La lesión de Bankart (rodete anteroinferior) y la lesión de Hill-Sachs (impactación de la cabeza humeral) son hallazgos característicos de la inestabilidad glenohumeral recurrente","El ligamento glenohumeral inferior es el principal estabilizador estático contra la luxación anterior con el brazo en abducción y rotación externa"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (85, '{"Brachial fascia.r","Lateral intermuscular septum of arm.r","Medial intermuscular septum of arm.r"}', 'Fascias del Brazo', 'Ligamento', 'La fascia braquial envuelve la musculatura del brazo; los tabiques intermusculares lateral y medial son extensiones profundas de esta fascia que se fijan al húmero, separando los compartimentos flexor (anterior) y extensor (posterior) del brazo.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:04:53.461089+00', '{"Estos tabiques delimitan los compartimentos que pueden verse afectados en un síndrome compartimental del brazo"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (86, '{"Articular capsule of elbow joint.r","Radial collateral ligament of elbow.r","Ulnar collateral ligament of elbow.r","Radial annular ligament.r","Quadrate ligament.r","Art cart of humerus distal end.r​","Art cart of radius head​.r","Art cart of ulna (proximal end).r"}', 'Articulación del Codo', 'Ligamento', 'Articulación compuesta (húmero-cubital, húmero-radial y radiocubital proximal) estabilizada por una cápsula común y los ligamentos colaterales radial y cubital. El ligamento anular rodea la cabeza del radio y permite su rotación durante la pronosupinación; el ligamento cuadrado refuerza la articulación radiocubital proximal.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:04:53.461089+00', '{"El ligamento colateral ulnar (medial) es clave en deportes de lanzamiento (ej. béisbol); su lesión por sobreuso en valgo repetido puede requerir reconstrucción quirúrgica (\"cirugía de Tommy John\")","La pronación dolorosa (subluxación de la cabeza radial fuera del ligamento anular) es frecuente en niños pequeños tras un tirón del brazo"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (87, '{"Interosseous membrane of forearm.r","Oblique cord or radio-ulnar syndesmosis.r","Antebrachial fascia.r","Thickened part of antebrachial fascia"}', 'Membrana Interósea y Fascia del Antebrazo', 'Ligamento', 'La membrana interósea conecta radio y cúbito en toda su extensión, transmite carga desde la mano hacia el codo y da origen a músculos profundos del antebrazo; el cordón oblicuo es un refuerzo fibroso accesorio proximal. La fascia antebraquial envuelve la musculatura y se engruesa localmente formando retináculos.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:04:53.461089+00', '{"La ruptura de la membrana interósea (lesión de Essex-Lopresti) redistribuye la carga hacia la muñeca y puede pasar desapercibida si se evalúa solo el codo o la muñeca por separado"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (88, '{"Dorsal radio-ulnar ligament.r","Palmar radio-ulnar ligament","Triangular fibro cartilage disc"}', 'Articulación Radiocubital Distal', 'Ligamento', 'Articulación entre las cabezas distales del radio y el cúbito, estabilizada por los ligamentos radiocubitales dorsal y palmar y por el complejo del fibrocartílago triangular, que además absorbe carga entre el cúbito y el carpo.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:04:53.461089+00', '{"Las lesiones del fibrocartílago triangular son causa frecuente de dolor cubital de muñeca, especialmente en deportes de carga axial o rotación forzada (ej. gimnasia, tenis)"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (89, '{"Articular capsule of radiocarpal joint","Dorsal radiocarpal ligament.r","Palmar radiocarpal ligament.r","Radial collateral ligament of wrist.r","Ulnar collateral ligament of wrist.r","Dorsal ulnocarpal ligament","Palmar ulnocarpal ligament.r","Ulnotriquetral ligament","Radioscaphocapitate ligament","Art cart of radius distal end​.r","Art cart of ulna. (distal end).r"}', 'Articulación Radiocarpiana (Muñeca)', 'Ligamento', 'Articulación entre el radio distal (y el disco articular) con la hilera proximal del carpo (escafoides, semilunar, piramidal), estabilizada por una red de ligamentos radiocarpianos y ulnocarpianos dorsales y palmares que guían el movimiento y previenen la traslación excesiva del carpo.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Kaplan Anatomy Lecture Notes"}', '2026-08-16 17:04:53.461089+00', '{"El ligamento radioescafocapitate actúa como \"cabestrillo\" que sostiene el escafoides; su laxitud contribuye a la inestabilidad carpiana","Las fracturas de radio distal (ej. de Colles) frecuentemente comprometen la congruencia de esta articulación"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (90, '{"Intercarpal articulations.r","Dorsal intercarpal ligament","Lunotriquetral interosseous ligament","Scapholunate interosseus ligament","Scaphocapitate ligament","Triquetrocapitate ligament","Triquetrohamate ligament","Scaphotrapeziotrapezoidal ligament","Trapeziotrapezoidal interosseous ligament","Trapezoideocapitate interosseous ligament","Capitohamate interosseus ligament","Radiate carpal ligament","Dorsal scaphotriquetral ligament","Palmar scaphotriquetral ligament","Palmar capitohamate ligament","Palmar lunotriquetral ligament","Palmar trapezoideocapitate ligament","Art cart of capitate bone​","Art cart of hamate bone​","Art cart of lunate bone","Art cart of pisiform bone ​","Art cart of scaphoid bone​","Art cart of trapezium bone​","Art cart of trapezoid bone​","Art cart of triquetrum bone"}', 'Articulaciones Intercarpianas', 'Ligamento', 'Red de ligamentos interóseos cortos que conectan entre sí los huesos del carpo (dentro de cada hilera y entre hileras), dando estabilidad y coherencia mecánica al carpo como una unidad funcional durante los movimientos de la muñeca.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Kaplan Anatomy Lecture Notes"}', '2026-08-16 17:04:53.461089+00', '{"El ligamento escafolunar es el más clínicamente relevante: su lesión produce inestabilidad escafolunar, que sin tratamiento puede evolucionar a un patrón de colapso conocido como SLAC (scapholunate advanced collapse)","La inestabilidad carpiana es una causa frecuente de dolor crónico de muñeca tras un esguince mal diagnosticado"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (91, '{"Pisohamate ligament","Pisometacarpal ligament.r","Pisotriquetral ligament","Ulnopisiform ligament"}', 'Ligamentos del Pisiforme', 'Ligamento', 'El pisiforme es un hueso sesamoideo incluido en el tendón del flexor cubital del carpo; se conecta al resto del carpo y a la base del 5º metacarpiano mediante estos ligamentos cortos, que en conjunto funcionan como la continuación distal de ese tendón.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:04:53.461089+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (92, '{"Flexor retinaculum","Extensor retinaculum of wrist"}', 'Retináculos de la Muñeca', 'Ligamento', 'El retináculo flexor (ligamento transverso del carpo) forma el techo del túnel carpiano, por donde pasan el nervio mediano y los tendones flexores; el retináculo extensor organiza los tendones extensores en compartimentos en el dorso de la muñeca.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:04:53.461089+00', '{"El retináculo flexor es la estructura que, al comprimir el nervio mediano contra el contenido del túnel carpiano, define el síndrome del túnel carpiano","La tenosinovitis de De Quervain afecta el primer compartimento extensor, bajo el retináculo extensor"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (93, '{"Dorsal carpometacarpal ligaments","Palmar carpometacarpal ligaments"}', 'Articulaciones Carpometacarpianas', 'Ligamento', 'Conectan la hilera distal del carpo con la base de los metacarpianos. La carpometacarpiana del pulgar (trapeciometacarpiana), en silla de montar, es la más móvil y clínicamente relevante del grupo.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:04:53.461089+00', '{"Rizartrosis: artrosis de la articulación trapeciometacarpiana del pulgar, muy frecuente y limitante para la fuerza de pinza"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (94, '{"Interosseous metacarpal ligaments","Dorsal metacarpal ligaments","Palmar metacarpal ligaments","Deep transverse metacarpal ligament"}', 'Ligamentos Metacarpianos', 'Ligamento', 'Ligamentos cortos que conectan los metacarpianos entre sí, dando estabilidad al arco transverso de la mano; el ligamento transverso metacarpiano profundo conecta las placas volares de las articulaciones metacarpofalángicas 2ª a 5ª.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:04:53.461089+00', '{}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (95, '{"Articular capsules of metacarpophalangeal joints","Collateral ligaments of metacarpophalangeal joints.r","Collateral ligaments of metacarpal joints.r","Palmar ligaments of metacarpophalangeal joints.r","Oblique ligament of 1st finger.r","Art carts of metacarpal bones"}', 'Articulaciones Metacarpofalángicas', 'Ligamento', 'Articulaciones condíleas entre metacarpianos y falanges proximales, estabilizadas por ligamentos colaterales (más tensos en flexión) y placas volares. La del pulgar tiene refuerzos ligamentarios propios, incluido el oblicuo.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:04:53.461089+00', '{"El ligamento colateral cubital de la metacarpofalángica del pulgar es el más lesionado del grupo (\"pulgar del guardabosque/esquiador\"), por estrés en valgo forzado"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (96, '{"Articular capsules of proximal interphalangeal joints","Articular capsules of distal interphalangeal joints","Collateral ligaments of interphalangeal joints.r","Collateral ligaments of distal phalangeal joints.r","Palmar ligaments of interphalangeal joints.r","Palmar ligaments of distal phalangeal joints.r","Art carts of proximal phalanges","Art carts of middle phalanges","Art carts of distal phalanges"}', 'Articulaciones Interfalángicas', 'Ligamento', 'Articulaciones en bisagra (proximales y distales) entre las falanges de los dedos, estabilizadas por ligamentos colaterales y placas volares que permiten un movimiento de flexo-extensión muy congruente y estable.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:04:53.461089+00', '{"La lesión de la placa volar es frecuente en traumatismos deportivos por hiperextensión del dedo (\"dedo en gatillo\" traumático o \"jammed finger\")","La artrosis interfalángica distal (nódulos de Heberden) es muy común en la población adulta mayor"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (97, '{"Annular ligament(A1) of 1st finger.r","Annular ligament(A2) of 1st finger.r","Annular ligaments of 2nd finger A1-A5.r","Annular ligaments of 3rd finger A1-A5.r","Annular ligaments of 4th finger A1-A5.r","Annular ligaments of 5th finger A1-A5.r","Cruciform ligaments of 2nd finger.r","Cruciform ligaments of 3rd finger.r","Cruciform ligaments of 4th finger.r","Cruciform ligaments of 5th finger.r","Fibrous sheath of digits of hand","Fibrous sheath of digits of hand thumb"}', 'Vainas Fibrosas de los Dedos (Poleas)', 'Ligamento', 'Túneles fibrosos (poleas anulares A1-A5 y cruciformes) que recubren los tendones flexores a lo largo de cada dedo, manteniéndolos aplicados al hueso durante la flexión y evitando que se separen de la falange ("efecto cuerda de arco").', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:04:53.461089+00', '{"Dedo en resorte (trigger finger): engrosamiento del tendón o de la polea A1 que bloquea el deslizamiento del tendón flexor, con un \"chasquido\" característico al extender el dedo","Las lesiones de polea son frecuentes en escalada deportiva por sobrecarga en flexión forzada"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (99, '{"Subacromial bursa.r","Subacromial-subdeltoid bursa.r","Subcutaneous acromial bursa.r","Subdeltoid bursa.r","Coracobrachial bursa.r","Infraserratus bursa.r","Supraserratus bursa.r","Subtendinous bursa of infraspinatus muscle.r","Subtendinous bursa of subscapularis.r","Subtendinous bursa of teres major.r","Subtendinous bursa of trapezius.r","Subtendinous bursa of latissimus dorsi.r"}', 'Bursas del Hombro', 'Ligamento', 'Bolsas serosas que reducen la fricción entre tendones, músculos y planos óseos alrededor del hombro. La bursa subacromial-subdeltoidea es la más grande y clínicamente relevante, ubicada entre el manguito rotador y el arco coracoacromial/deltoides.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:05:44.300265+00', '{"Bursitis subacromial: causa muy frecuente de dolor de hombro, a menudo asociada al síndrome de pinzamiento subacromial","La bursa subacromial-subdeltoidea suele estar comunicada, por lo que su inflamación puede simular o coexistir con patología del manguito rotador"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (100, '{"Bicipitoradial bursa","Intratendinous olecranon bursa.r","Subcutaneous olecranon bursa.r","Interosseous cubital bursa.r","Subtendinous bursa of triceps brachii.r"}', 'Bursas del Codo', 'Ligamento', 'Bolsas serosas periarticulares del codo; la más clínicamente relevante es la bursa olecraneana subcutánea, superficial a la punta del olécranon.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)"}', '2026-08-16 17:05:44.300265+00', '{"Bursitis olecraneana: inflamación frecuente por apoyo prolongado o traumatismo directo repetido sobre el codo (\"codo de estudiante\"); puede ser séptica o no séptica"}');
INSERT INTO public.anatomy_structures (id, mesh_names, display_name, type, description, sources, created_at, clinical_relevance) VALUES (101, '{"Abductor pollicis longus tendon sheath","Extensor carpi radialis brevis tendon sheath","Extensor carpi radialis longus tendon sheath","Extensor carpi ulnaris tendon sheath","Extensor digiti minimi tendon sheath","Extensor digitorum - Extensor indicis tendon sheath","Extensor pollicis brevis tendon sheath","Extensor pollicis longus tendon sheath","Flexor carpi radialis tendon sheath","Flexor pollicis longus tendon sheath","Common flexor tendon sheath","Synovial sheaths of fingers"}', 'Vainas Tendinosas de la Muñeca y Mano', 'Ligamento', 'Envolturas sinoviales que rodean los tendones flexores y extensores a su paso por la muñeca y los dedos, reduciendo la fricción contra los retináculos y las poleas óseas.', '{"Latarjet - Anatomía Humana, Tomo 1 (4ª ed.)","Kaplan Anatomy Lecture Notes"}', '2026-08-16 17:05:44.300265+00', '{"Tenosinovitis de De Quervain: inflamación de la vaina del primer compartimento extensor (abductor largo y extensor corto del pulgar)","Tenosinovitis flexora (dedo en resorte): inflamación de la vaina flexora que, junto con la polea A1, bloquea el deslizamiento del tendón","Las infecciones de las vainas sinoviales de los dedos pueden diseminarse rápidamente a lo largo de todo el trayecto tendinoso"}');
