-- Ejecutar este script completo en el SQL Editor de Supabase
-- (Project > SQL Editor > New query > pegar > Run)
--
-- Esta tabla mapea nombres de malla (mesh) del modelo 3D
-- public/upper-limb-anatomy.glb a su nombre clínico en español y descripción.
-- El modelo es "Open3DModel - Upper limb" (AnatomyTOOL.org / RadboudUMC / LUMC),
-- licencia CC BY-SA 4.0. Varias mallas del modelo (partes de un mismo músculo,
-- ligamentos de una misma articulación, cartílago articular correspondiente,
-- etc.) apuntan a la misma fila mediante el array mesh_names, para que la
-- ficha mostrada sea la de la estructura completa aunque el clic caiga en
-- una porción específica.
--
-- Cobertura: 532/532 mallas clickeables del modelo (100%), en 101 fichas:
-- 15 Hueso, 44 Musculo, 21 Ligamento (incluye cartílago articular y
-- bursas/vainas sinoviales de la articulación correspondiente), 13 Nervio,
-- 8 Vaso (arterias y venas).
--
-- Este archivo es un volcado completo y reproducible del estado actual de
-- la tabla (generado con pg_dump --data-only --column-inserts). Para
-- recrearla desde cero, correr todo el archivo tal cual.

create table if not exists public.anatomy_structures (
  id bigint generated by default as identity primary key,
  mesh_names text[] not null,
  display_name text not null,
  type text not null, -- 'Hueso' | 'Musculo' | 'Ligamento' | 'Nervio' | 'Vaso'
  description text not null,
  sources text[] default '{}',
  created_at timestamptz default now(),
  clinical_relevance text[] default '{}'
);

alter table public.anatomy_structures enable row level security;

do $$
begin
  if not exists (
    select 1 from pg_policies
    where tablename = 'anatomy_structures' and policyname = 'Public read access'
  ) then
    create policy "Public read access"
      on public.anatomy_structures
      for select
      to anon, authenticated
      using (true);
  end if;
end $$;

-- Datos (borra todo y vuelve a insertar, para que el script sea re-ejecutable)
truncate table public.anatomy_structures restart identity;


-- Data for Name: anatomy_structures; Type: TABLE DATA; Schema: public; Owner: -



SELECT pg_catalog.setval('public.anatomy_structures_id_seq', 101, true);

